15	export class DsDialog extends ForwardsFocus(Base) {
16	  static observedAttributes = ["open", "label", "description", "dismissible", "hidden"];
17	  #dialog;
18	  #title;
19	  #description;
20	  #previousFocus;
21	  #lockedDocument;
22	  #wasOpen = false;
23	
24	  constructor() {
25	    super();
26	    const root = this.attachShadow({ mode: "open" });
27	    root.adoptedStyleSheets = [styleSheet()];
28	    root.innerHTML = `<dialog part="dialog" closedby="none" aria-labelledby="title" aria-modal="true">
29	      <h2 id="title" part="title" tabindex="-1"></h2>
30	      <p id="description" part="description" hidden></p>
31	      <div part="content"><slot></slot></div>
32	      <div part="actions"><slot name="actions"></slot></div>
33	    </dialog>`;
34	    this.#dialog = root.querySelector("dialog");
35	    this.#title = root.querySelector("h2");
36	    this.#description = root.querySelector("p");
37	    this.#dialog.addEventListener("cancel", (event) => {
38	      event.preventDefault();
39	      this.#requestCancel();
40	    });
41	    this.#dialog.addEventListener("close", () => {
42	      if (!this.#dialog.open && this.#wasOpen) {
43	        this.removeAttribute("open");
44	        this.#finishClose();
45	      }
46	    });
47	  }
48	
49	  connectedCallback() {
50	    this.#sync();
51	  }
52	
53	  disconnectedCallback() {
54	    if (this.#dialog.open) this.#dialog.close();
55	    this.#finishClose();
56	  }
57	
58	  attributeChangedCallback() {
59	    this.#sync();
60	  }
61	
62	  #sync() {
63	    this.#dialog.setAttribute("closedby", this.dismissible ? "closerequest" : "none");
64	    this.#title.textContent = this.label;
65	    this.#description.textContent = this.description;
66	    this.#description.hidden = !this.description;
67	    if (this.description) this.#dialog.setAttribute("aria-describedby", "description");
68	    else this.#dialog.removeAttribute("aria-describedby");
69	    if (this.open && !this.hidden && this.isConnected) {
70	      if (this.#dialog.open) return;
71	      this.#previousFocus = deepestFocus(this.ownerDocument);
72	      this.#dialog.showModal();
73	      this.#wasOpen = true;
74	      this.#lockScroll();
75	      this.ownerDocument.addEventListener("keydown", this.#onKeydown);
76	      const initial = this.querySelector("[autofocus]");
77	      (initial ?? this.#title).focus({ preventScroll: true });
78	    } else if (this.#dialog.open) {
79	      this.#dialog.close();
80	      this.#finishClose();
81	    }
82	  }
83	
84	  #requestCancel() {
85	    if (!this.dismissible) return;
86	    if (
87	      this.dispatchEvent(new Event("cancel", { cancelable: true, bubbles: true, composed: true }))
88	    )
89	      this.close();
90	  }
91	
92	  #onKeydown = (event) => {
93	    if (
94	      !this.#dialog.open ||
95	      event.defaultPrevented ||
96	      event.isComposing ||
97	      openDialogs.get(this.ownerDocument)?.at(-1) !== this
98	    )
99	      return;
100	    if (event.key === "Escape") {
101	      // Apply the host cancellation contract after child controls have handled Escape.
102	      // Keep native close requests enabled for platform gestures such as system back.
103	      event.preventDefault();
104	      this.#requestCancel();
105	      return;
106	    }
107	    if (event.key !== "Tab") return;
108	    const items = tabbables(this.#dialog);
109	    const active = deepestFocus(this.ownerDocument);
110	    const index = items.indexOf(active);
111	    if (!items.length) {
112	      event.preventDefault();
113	      this.#title.focus();
114	    } else if (
115	      index < 0 ||
116	      (!event.shiftKey && index === items.length - 1) ||
117	      (event.shiftKey && index === 0)
118	    ) {
119	      event.preventDefault();
120	      items[event.shiftKey ? items.length - 1 : 0].focus();
121	    }
122	  };
123	
124	  #lockScroll() {
125	    const document = this.ownerDocument;
126	    const dialogs = openDialogs.get(document) ?? [];
127	    dialogs.push(this);
128	    openDialogs.set(document, dialogs);
129	    let lock = scrollLocks.get(document);
130	    if (!lock) {
131	      const style = document.documentElement.style;
132	      lock = {
133	        count: 0,
134	        overflow: style.getPropertyValue("overflow"),
135	        priority: style.getPropertyPriority("overflow"),
136	      };
137	      scrollLocks.set(document, lock);
138	      style.setProperty("overflow", "hidden");
139	    }
140	    lock.count += 1;
141	    this.#lockedDocument = document;
142	  }
143	
144	  #finishClose() {
145	    const document = this.#lockedDocument;
146	    if (document) {
147	      const dialogs = openDialogs.get(document);
148	      dialogs.splice(dialogs.indexOf(this), 1);
149	      if (!dialogs.length) openDialogs.delete(document);
150	      document.removeEventListener("keydown", this.#onKeydown);
151	      const lock = scrollLocks.get(document);
152	      if (--lock.count === 0) {
153	        if (lock.overflow)
154	          document.documentElement.style.setProperty("overflow", lock.overflow, lock.priority);
155	        else document.documentElement.style.removeProperty("overflow");
156	        scrollLocks.delete(document);
157	      }
158	      this.#lockedDocument = undefined;
159	    }
160	    if (!this.#wasOpen) return;
161	    this.#wasOpen = false;
162	    if (this.#previousFocus?.isConnected) this.#previousFocus.focus({ preventScroll: true });
163	    this.#previousFocus = undefined;
164	    this.dispatchEvent(new Event("close", { bubbles: true, composed: true }));
165	  }
166	
167	  get [focusTarget]() {
168	    return this.#title;
169	  }
170	  get open() {
171	    return this.hasAttribute("open");
172	  }
173	  set open(value) {
174	    this.toggleAttribute("open", Boolean(value));
175	  }
176	  get label() {
177	    return this.getAttribute("label") ?? "";
178	  }
179	  set label(value) {
180	    this.setAttribute("label", value);
181	  }
182	  get description() {
183	    return this.getAttribute("description") ?? "";
184	  }
185	  set description(value) {
186	    this.setAttribute("description", value);
187	  }
188	  get dismissible() {
189	    return this.getAttribute("dismissible") !== "false";
190	  }
191	  set dismissible(value) {
192	    this.setAttribute("dismissible", String(Boolean(value)));
193	  }
194	  showModal() {
195	    this.open = true;
196	  }
197	  close() {
198	    this.open = false;
199	  }
200	}
